    {"id":8,"name":"Toroidal-field coils / magnetic probes","module":"toroidal_field_coils","function":"analyze_toroidal_field_coil","execution_contract":{"schema_version":"1.0","execution_level":"analysis_pipeline","completeness":"complete","input_specs":[{"name":"time_s","unit":"s","required":True,"description":"Finite strictly increasing time samples; at least two."},{"name":"signal","unit":"signal_kind-dependent","required":True,"description":"Finite 1-D samples aligned with time_s."},{"name":"signal_kind","unit":"text","required":True,"description":"field, current, or directly calibrated voltage."},{"name":"calibration_T_per_unit","unit":"T per input unit","required":True,"description":"Explicit calibration coefficient; field mode requires 1."},{"name":"baseline","unit":"input units","required":False,"description":"Optional finite baseline subtracted before calibration."},{"name":"signal_uncertainty","unit":"input units, 1-sigma","required":False,"description":"Optional independent pointwise uncertainty."},{"name":"calibration_uncertainty_T_per_unit","unit":"T per input unit, 1-sigma","required":False,"description":"Optional calibration coefficient uncertainty."},{"name":"pickup_voltage_V","unit":"V","required":False,"description":"Optional separate calibrated pickup-coil voltage trace for integration mode."},{"name":"pickup_sensitivity_V_per_T_per_s","unit":"V/(T s^-1)","required":False,"description":"Validated sensitivity for V=S*dB/dt; required for integration."},{"name":"initial_field_T","unit":"T","required":False,"description":"Required boundary condition for integrated field."},{"name":"pickup_voltage_baseline_V","unit":"V","required":False,"description":"Optional pickup-voltage baseline subtracted before integration."},{"name":"pickup_voltage_uncertainty_V","unit":"V, 1-sigma","required":False,"description":"Optional pointwise pickup-voltage uncertainty."},{"name":"pickup_sensitivity_uncertainty_V_per_T_per_s","unit":"V/(T s^-1), 1-sigma","required":False,"description":"Optional pickup sensitivity uncertainty."},{"name":"initial_field_uncertainty_T","unit":"T, 1-sigma","required":False,"description":"Optional uncertainty in the initial-field boundary condition."}],"output_specs":[{"name":"B_toroidal_T","unit":"T","description":"Calibrated field estimate or integrated field when using the dedicated pickup-voltage function."},{"name":"mean_B_toroidal_T","unit":"T","description":"Sample mean field."},{"name":"rms_B_toroidal_T","unit":"T","description":"Root-mean-square field."},{"name":"std_B_toroidal_T","unit":"T","description":"Sample standard deviation."},{"name":"peak_to_peak_B_toroidal_T","unit":"T","description":"Peak-to-peak field."},{"name":"sampling_rate_Hz","unit":"Hz","description":"Inverse median sample interval."},{"name":"sampling_interval_jitter_fraction","unit":"dimensionless","description":"Sampling interval standard deviation divided by mean."},{"name":"B_toroidal_uncertainty_T","unit":"T, 1-sigma","description":"Optional first-order uncertainty propagation."},{"name":"dB_dt_T_s","unit":"T s^-1","description":"Pickup voltage divided by validated sensitivity."},{"name":"delta_B_T","unit":"T","description":"Cumulative trapezoidal field change."},{"name":"pickup_integration_B_toroidal_T","unit":"T","description":"Field reconstructed from integrated calibrated pickup voltage plus the initial-field boundary condition."},{"name":"pickup_integration_B_uncertainty_T","unit":"T, 1-sigma","description":"Propagated integrated-field uncertainty from voltage noise, sensitivity and initial-field uncertainty."}],"assumptions":["Calibration is valid across signal range and bandwidth.","Signal and calibration uncertainties are independent.","Pickup voltage integration requires validated sensitivity and an initial-field boundary condition."],"preprocessing":["Validate dimensionality, finite values, lengths, strictly increasing time, calibration and uncertainty inputs."],"algorithm":"Calibrated field/current/directly calibrated voltage conversion with statistics and uncertainty; separate pickup-coil mode integrates dB/dt=V_corrected/S by cumulative trapezoids and adds the supplied initial field.","uncertainty_model":"First-order independent signal/calibration uncertainty; pickup integration propagates independent voltage noise, sensitivity uncertainty and initial-field uncertainty. Correlated drift, baseline uncertainty and model discrepancy are excluded.","limitations":["No automatic frequency-response correction or detrending.","Pickup integration requires independently validated transfer function and initial field.","No coil geometry, mutual inductance, saturation, equilibrium reconstruction or total-field inference from current alone."],"function_links":["tokamak_analysis.toroidal_field_coils.analyze_toroidal_field_coil","tokamak_analysis.toroidal_field_coils.integrate_pickup_coil_voltage"],"raw_data_to_physics":True}},
